/* Считаем количество карточек, которые были проектированы John Avon и у которых версионка для флайпа не является мощной. */
SELECT COUNT(*) 
FROM cards AS T1 
JOIN rulings AS T2 ON T1.uuid = T2.uuid 
WHERE T1.artist LIKE 'John Avon' AND T1.text NOT LIKE '%{P%}';

